#include <stdio.h>

struct Flags {
    unsigned int ready : 1;
    unsigned int mode  : 3;
    unsigned int prio  : 4;
};

int main(void) {
    struct Flags f = {0};
    f.ready = 1;
    f.mode  = 5;
    f.prio  = 9;
    printf("ready=%u mode=%u prio=%u\n", f.ready, f.mode, f.prio);
    printf("raw bytes: %02X %02X\n", (unsigned)((unsigned char*)&f)[0], (unsigned)((unsigned char*)&f)[1]);
    return 0;
}
